{
  "findings": [
    {
      "check_id": "CKV_AZURE_35",
      "title": "Storage account network access defaults to allow",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "MEDIUM",
      "explanation": "The network rules use default_action = \"Allow\", so requests not matched by an explicit rule are permitted. Setting the default to deny restricts access to approved rules and trusted service bypasses."
    },
    {
      "check_id": "AVD-AZU-0010",
      "title": "Trusted Microsoft Services bypass is not enabled",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "HIGH",
      "explanation": "The bypass list permits metrics and logging but omits AzureServices. Once default network access is denied, trusted Microsoft services requiring storage access would not be able to bypass the network restrictions."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account_network_rules\" \"notification_storage_rules\" {\n  storage_account_id = azurerm_storage_account.notification_storage.id\n  default_action     = \"Deny\"\n  ip_rules           = [\"127.0.0.1\"]\n  bypass             = [\"AzureServices\", \"Metrics\", \"Logging\"]\n}\n",
  "fix_summary": "Changed the storage account network default action from allow to deny. Added the AzureServices bypass while retaining the existing metrics and logging bypasses."
}
